 const [name,setName]=useState('');const [cardName,setCardName]=useState('');const [card,setCard]=useState('');const [expiry,setExpiry]=useState('');const [security,setSecurity]=useState('');const [zip,setZip]=useState('');const [submitting,setSubmitting]=useState(false);
