 const changeRewardsPhone=(value:string)=>{const next=findLoyaltyCustomer(state,value);if(normalizeCustomerPhone(value)!==normalizeCustomerPhone(rewardsPhone)){setRedeemReward(false);setProfileOpen(false);if(next)setPickupName(next.name);else if(matchedCustomer)setPickupName('');}setRewardsPhone(value);};
